+	if state.LastSyncedAt == nil {
+		t.Error("expected LastSyncedAt to be set")
+	}
+	if state.ErrorCode != string(domain.ErrDatabaseConnection) {
+		t.Errorf("expected error code, got: %s", state.ErrorCode)
+	}
+}
